recipes.code:
{
  "inputs": [
    {
      "id": "leadbay-token",
      "type": "promptString",
      "description": "Bearer token, set by the installer. Run `npx -y -p @leadbay/mcp@latest installer` and sign in with your browser.",
      "password": true
    }
  ],
  "servers": {
    "leadbay": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "-y",
        "@leadbay/mcp@0.27",
        "@leadbay/mcp@0.27.0"
      ],
      "env": {
        "LEADBAY_TOKEN": "${input:leadbay-token}",
        "LEADBAY_REGION": "fr",
        "LEADBAY_MCP_WRITE": "1",
        "LEADBAY_MCP_ADVANCED": "0",
        "LEADBAY_TELEMETRY_ENABLED": "true"
      }
    }
  }
}
